diff --git a/lib/mprintf.c b/lib/mprintf.c
index abe0df4..7344acd 100644
--- a/lib/mprintf.c
+++ b/lib/mprintf.c
@@ -85,7 +85,9 @@ enum {
   FLAGS_CHAR       = 1 << 17, /* %c story */
   FLAGS_FLOATE     = 1 << 18, /* %e or %E */
   FLAGS_FLOATG     = 1 << 19, /* %g or %G */
-  FLAGS_SUBSTR     = 1 << 20  /* no input, only substring */
+  FLAGS_SUBSTR     = 1 << 20, /* no input, only substring */
+  FLAGS_STRCAP     = 1 << 21, /* %s precision caps the copy */
+  FLAGS_STRARG     = 1 << 22  /* %s precision is a counted argument */
 };

 enum {
@@ -975,6 +977,9 @@ static bool out_string(void *userp,
   int prec = p->prec;
   size_t len;

+  if(prec > 0)
+    flags |= FLAGS_STRCAP;
+
   if(!str) {
     /* Write null string if there is space. */
     if(prec == -1 || prec >= (int)CURL_CSTRLEN(nilstr)) {
@@ -1014,8 +1019,22 @@ static bool out_string(void *userp,
                   (const unsigned char *)str, len, donep))
       return TRUE;
   }
-  else if(stream_zrun(userp, stream, streamn, str, len, donep))
-    return TRUE;
+  else {
+    size_t hard = len;
+    size_t n;
+    size_t i = 0;
+    size_t budget = hard;
+
+    if((flags & (FLAGS_STRCAP | FLAGS_STRARG)) ==
+       (FLAGS_STRCAP | FLAGS_STRARG) && hard)
+      budget++;
+    while(i < budget && str[i])
+      i++;
+    n = (i > hard) ? hard : i;
+    if(stream_run(userp, stream, streamn,
+                  (const unsigned char *)str, n, donep))
+      return TRUE;
+  }
   if(flags & FLAGS_LEFT) {
     if(stream_pad(userp, stream, streamn, ' ', width, donep))
       return TRUE;

diff --git a/lib/mprintf.c b/lib/mprintf.c
index 1afa530..a8b4d0e 100644
--- a/lib/mprintf.c
+++ b/lib/mprintf.c
@@ -87,7 +87,8 @@ enum {
   FLAGS_FLOATG     = 1 << 19, /* %g or %G */
   FLAGS_SUBSTR     = 1 << 20, /* no input, only substring */
   FLAGS_STRCAP     = 1 << 21, /* %s precision caps the copy */
-  FLAGS_STRARG     = 1 << 22  /* %s precision is a counted argument */
+  FLAGS_STRARG     = 1 << 22, /* %s precision is a counted argument */
+  FLAGS_STRFIELD   = 1 << 23  /* %s field is not left-justified */
 };

 enum {
@@ -979,6 +980,8 @@ static bool out_string(void *userp,

   if(prec > 0)
     flags |= FLAGS_STRCAP;
+  if(flags & (FLAGS_PREC | FLAGS_PRECPARAM))
+    flags |= FLAGS_STRARG;

   if(!str) {
     /* Write null string if there is space. */
@@ -1024,6 +1027,9 @@ static bool out_string(void *userp,
     size_t n;
     size_t i = 0;
     size_t budget = hard;
+    size_t j;
+    size_t jbudget;
+    size_t jgot;

     if((flags & (FLAGS_STRCAP | FLAGS_STRARG)) ==
        (FLAGS_STRCAP | FLAGS_STRARG) && hard)
@@ -1031,6 +1037,18 @@ static bool out_string(void *userp,
     while(i < budget && str[i])
       i++;
     n = (i > hard) ? hard : i;
+
+    if((flags & (FLAGS_STRARG | FLAGS_STRFIELD)) ==
+       (FLAGS_STRARG | FLAGS_STRFIELD) && hard) {
+      j = 0;
+      jbudget = hard + 1;
+      while(j < jbudget && str[j])
+        j++;
+      jgot = (j > hard) ? hard : j;
+      if(jgot < n)
+        n = jgot;
+    }
+
     if(stream_run(userp, stream, streamn,
                   (const unsigned char *)str, n, donep))
       return TRUE;

